static void lights_init(void)
{
    nlarea = lght ? *(const u32 *)lght : 0;
    alights = mem_alloc(MEM_SCENE, (nlarea ? nlarea : 1) * 4 * sizeof(RenderLight));
    memset(alights, 0, (nlarea ? nlarea : 1) * 4 * sizeof(RenderLight));
    int tc = scene_type(sc, "LightCtrlCube"), ty = scene_type(sc, "LightCtrlCylinder");
    nlareas = 0;
    for (u32 i = 0; i < sc->nobjs; i++) nlareas += sc->objs[i].type == tc || sc->objs[i].type == ty;
    lareas = mem_alloc(MEM_SCENE, (nlareas + 1) * sizeof(int));
    nlareas = 0;
    for (u32 i = 0; i < sc->nobjs; i++) if (sc->objs[i].type == tc || sc->objs[i].type == ty) lareas[nlareas++] = i;
    for (int i = 0; i < nlareas - 1; i++) { /* LightAreaHolder::sort: selection by arg1, swapping */
        int sel = i;
        for (int j = i + 1; j < nlareas; j++) if (sc->objs[lareas[sel]].arg[1] > sc->objs[lareas[j]].arg[1]) sel = j;
        int t = lareas[i]; lareas[i] = lareas[sel]; lareas[sel] = t;
    }
    row_larea = mem_alloc(MEM_SCENE, sc->nobjs + 1);
    memset(row_larea, -1, sc->nobjs + 1);
    row_larea_t = mem_alloc(MEM_SCENE, (sc->nobjs + 1) * sizeof(unsigned));
    plight.area = -1;
}

/* tryFindLightID + getAreaLightNameInZoneData + findAreaLight: the area light at p */
static int light_area_at(V3 p)
{
    if (!lght) return 0;
    for (int i = 0; i < nlareas; i++) {
        const Row *r = &sc->objs[lareas[i]];
        if (!area_inside(r, p)) continue;
        const unsigned char *z = lght + 16 + 208 * nlarea;
        for (u32 k = 0, nz = *(const u32 *)(lght + 8); k < nz; k++) {
            u32 n = *(const u32 *)z;
            if (k == r->zone)
                for (u32 j = 0; j < n; j++)
                    if (*(const s32 *)(z + 4 + 8 * j) == r->arg[0]) return (int)*(const u32 *)(z + 8 + 8 * j);
            z += 4 + 8 * n;
        }
        return (int)*(const u32 *)(lght + 12);
    }
    return (int)*(const u32 *)(lght + 4);
}

static void blend_light(RenderLight *o, const RenderLight *a, const RenderLight *b, float k)
{
    for (int c = 0; c < 3; c++) {
        for (int l = 0; l < 2; l++) {
            o->col[l][c] = a->col[l][c] + (b->col[l][c] - a->col[l][c]) * k;
            o->pos[l][c] = a->pos[l][c] + (b->pos[l][c] - a->pos[l][c]) * k;
        }
        o->amb[c] = a->amb[c] + (b->amb[c] - a->amb[c]) * k;
    }
    o->amb_a = a->amb_a + (b->amb_a - a->amb_a) * k;
    o->alpha2 = a->alpha2 + (b->alpha2 - a->alpha2) * k; /* blendActorLightInfo: getInterpolateValue */
}

static void lights_update(V3 eye, V3 target, V3 up, V3 player)
{
    if (!lght) return;
    V3 back = vnorm(vsub(eye, target)), right = vnorm(vcross(up, back)), u = vcross(back, right);
    for (u32 ar = 0; ar < nlarea; ar++)
        for (int t = 0; t < 4; t++) {
            const unsigned char *ty = lght + 16 + 208 * ar + 16 + 48 * t;
            RenderLight *L = &alights[4 * ar + t];
            for (int k = 0; k < 2; k++) {
                const unsigned char *l = ty + 20 * k;
                const float *pos = (const float *)(l + 4);
                V3 w = *(const u32 *)(l + 16) ? vadd(eye, vadd(vadd(vmul(right, pos[0]), vmul(u, pos[1])), vmul(back, pos[2])))
                                             : v3(pos[0], pos[1], pos[2]);
                L->pos[k][0] = w.x; L->pos[k][1] = w.y; L->pos[k][2] = w.z;
                for (int c = 0; c < 3; c++) L->col[k][c] = l[c] / 255.0f;
            }
            for (int c = 0; c < 3; c++) L->amb[c] = ty[40 + c] / 255.0f;
            L->amb_a = ty[43] / 255.0f;
            L->alpha2 = *(const u32 *)(ty + 44) / 255.0f; /* mAlpha2: GX_LIGHT2's (render.c air_matrix) */
        }
    /* the player: tryFindNewAreaLight, then updateLightBlend from the old area's light to the new one */
    int a = light_area_at(player);
    if (a != plight.area) {
        int it = *(const s32 *)(lght + 16 + 208 * a);
        plight.from = plight.area; plight.t = 0;
        plight.n = plight.area < 0 || it == 0 ? 0 : it < 0 ? 30 : it;
        plight.area = a;
    }
    const RenderLight *to = &alights[4 * a + LIGHT_PLAYER];
    if (plight.n && ++plight.t < plight.n) blend_light(&plight.cur, &alights[4 * plight.from + LIGHT_PLAYER], to, (float)plight.t / plight.n);
    else { plight.n = 0; plight.cur = *to; }
}

static const RenderLight *default_light(int t)
{
    return &alights[4 * (lght ? *(const u32 *)(lght + 4) : 0) + t];
}

/* the light of a placed row's class (TLGT; `dflt` when its class is not known) in the area light holding p */
static void use_row_light(int row, V3 p, int dflt)
{
    if (row < 0) { render_light(default_light(dflt)); return; }
    int t = sc->type_light ? sc->type_light[sc->objs[row].type] : 255;
    if (row_larea[row] < 0 || game_frame - row_larea_t[row] >= 30) {
        row_larea[row] = (signed char)light_area_at(p);
        row_larea_t[row] = game_frame;
    }
    render_light(&alights[4 * row_larea[row] + (t < 4 ? t : dflt)]);
}

/* the BTPS entry of a "<class>/<clip>" (its texture pattern: MR::startBtp / the same-name BTP of an action), NULL */
static const u8 *btp_entry(const char *key)
{
    const u8 *q = sc->btps;
    for (u32 i = 0; q && i < sc->nbtps; i++) {
        u32 nm = q[32], fr = *(const u16 *)(q + 34), len = 36 + nm * (1 + fr);
        if (!strcmp((const char *)q, key)) return q;
        q += len + (-len & 3);
    }
    return NULL;
}
/* a texture pattern at its frame on a model's groups (SWAP kind 0x80 | slot); e NULL: their own textures */
static void btp_apply(const Model *md, const u8 *e, float frame)
{
    u32 nm = e ? e[32] : 0, fr = e ? *(const u16 *)(e + 34) : 0;
    int f = (int)frame;
    if (fr) f = e[33] == 2 || e[33] == 4 ? f % (int)fr : f < 0 ? 0 : f >= (int)fr ? (int)fr - 1 : f; /* its loop mode */
    for (u32 g = 0; g < md->vu_ngroups; g++) {
        VuGroup *v = &((Model *)md)->vu[g];
        if (!(v->swap_kind & 0x80)) continue;
        int k = 0;
        for (u32 i = 0; i < nm; i++) {
            const u8 *s = e + 36 + i * (1 + fr);
            if (s[0] == (v->swap_kind & 0x7F)) k = s[1 + f];
        }
        if (k < v->nswap) v->tex = v->swap[k];
    }
}
/* a model's BRKC track (tools/slice.py brkc_chunk: a BRK's C0, as MR::startBrk plays it) at its frame on its blend 4
 * groups */
static void brkc_apply(const Model *md, unsigned frame)
{
    const u8 *q = sc->brkc;
    for (u32 i = 0; q && i < sc->nbrkc; i++) {
        u32 n = *(const u16 *)(q + 34);
        if (!strcmp((const char *)q, md->name)) {
            u32 f = q[32] == 2 || q[32] == 4 ? frame % n : frame < n ? frame : n - 1;
            render_group_tint(md, q[36 + 4 * f], q[37 + 4 * f], q[38 + 4 * f]);
            return;
        }
        q += 36 + 4 * n;
    }
}
u32 prof_fxa, prof_shadow; /* fx_anim + se_anim in draw_skin; walker shadows (profiling) */
/* MR::startBva: a model's BVA "<model>/<bva>" at frame (its loop mode) hides its groups' shapes; NULL or none shows them */
static void bva_apply(const Model *md, const char *key, float frame)
{
    const u8 *q = md->bvas, *e = NULL;
    for (u32 i = 0; q && key && i < md->nbvas; i++) {
        if (!strcmp((const char *)q, key)) { e = q; break; }
        q += 36 + 4u * *(const u16 *)(q + 32) * q[35];
    }
    u32 n = e ? *(const u16 *)(e + 32) : 0, f = frame < 0 ? 0 : (u32)frame;
    if (e) f = e[34] == 2 || e[34] == 4 ? f % n : f < n ? f : n - 1;
    for (u32 g = 0; g < md->vu_ngroups; g++)
        ((Model *)md)->vu[g].hide = e && g / 32 < e[35] ? ((const u32 *)(e + 36))[f * e[35] + g / 32] >> (g % 32) & 1 : 0;
}
static const char *bva_key; /* draw_skin: a BVA started apart from the clip (startBva), at bva_frame; else the clip's */
static float bva_frame;
static int sbp_bva_row = -1; /* StinkBugParent without its child (update_sbp) */
static int nchg; /* ChipGroup states made (chip_group_of) */
static int nfbs; /* FountainBig states made (update_fountains) */
static void draw_skin(const Model *md, const float m[16], Anim *a)
{
    if (md == m_mario_skin) render_light(&plight.cur);
    u32 c0 = cycles();
    if (a->clip_id >= 0) {
        /* whether a clip has effect / sound rows, by clip (its name checks the slot): most have none */
        static struct { const char *name; u8 nofx, nose; } has[512];
        const char *cn = sc->clips[a->clip_id].name;
        typeof(has[0]) *h = &has[a->clip_id & 511];
        if (h->name != cn) { h->name = cn; h->nofx = h->nose = 0; }
        if (!h->nofx) { /* EffectKeeper's animation rows; Mario's clips are his group's ("mario/<clip>", tools/jpa.py NAMED_ANIMS) */
            char fk[48];
            snprintf(fk, sizeof fk, strchr(cn, '/') ? "%s" : "mario/%s", cn);
            h->nofx = !fx_anim(fk, a->fx_seen == a->clip_id + 1 ? a->fx_frame : -1.0f, a->frame, m, (const float (*)[16])a->world, a);
        }
        if (!h->nose) { /* its animation sounds (.bas: MR::startBas / actorSoundMovement); Mario's clips are MarioAnime's.
           * ponytail: only while drawn */
            char key[48];
            snprintf(key, sizeof key, strchr(cn, '/') ? "%s" : "marioanime/%s", cn);
            float at[3] = {m[12], m[13], m[14]};
            h->nose = !se_anim(key, a->fx_seen == a->clip_id + 1 ? a->fx_frame : -1.0f, a->frame, at, a);
        }
        prof_fxa += cycles() - c0;
        a->fx_seen = a->clip_id + 1;
        a->fx_frame = a->frame;
    }
    if (md->btp && a->clip_id >= 0) { /* its clip's texture pattern (the same-name BTP), else its own textures */
        static struct { const char *name; const u8 *e; } bc[256];
        const char *cn = sc->clips[a->clip_id].name;
        typeof(bc[0]) *c = &bc[a->clip_id & 255];
        if (c->name != cn) { c->name = cn; c->e = btp_entry(cn); }
        btp_apply(md, c->e, a->frame);
    }
    if (md->nbvas) { /* its visibility: a BVA started apart, else its clip's same-name one */
        if (bva_key) bva_apply(md, bva_key, bva_frame);
        else bva_apply(md, a->clip_id >= 0 ? sc->clips[a->clip_id].name : NULL, a->frame);
    }
    bva_key = NULL;
    float cm[16]; /* culled about its root joint as posed (a demo clip may carry the body far from its origin:
                   * RosettaReading's DemoRosettaReading puts her 220 off, on her chair) */
    memcpy(cm, m, sizeof cm);
    if (a->skin && a->skin->njoints) {
        const float *j = a->world[0];
        for (int k = 0; k < 3; k++) cm[12 + k] += m[k] * j[12] + m[4 + k] * j[13] + m[8 + k] * j[14];
    }
    if (render_model_visible(md, cm)) render_skinned_visible(md, m, anim_drw(a)); /* culled: no draw matrices made */
}
/* a one-shot effect standing on `up` at p */
static void fx_at(int fx, V3 p, V3 up)
{
    float m[16];
    basis_matrix(m, p, up, v3(0, 0, 1), 0);
    fx_emit(fx, m);
}
#define MAX_ZONES 64

/* Stage switches (Petari StageSwitch.cpp): ids below 1000 belong to the row's zone (128 each), the rest are the
 * galaxy's (id - 1000). One bit each, all off at the start; sw_changed makes the frame rebind what appear switches
 * show. ponytail: switches are not saved */
#define SW_PER_ZONE 128
static unsigned char sw_bits[(MAX_ZONES + 1) * SW_PER_ZONE / 8];
static int sw_changed;
/* the bits as update_switches last acted on them: sw_set marks them dirty, and it rebinds only when they differ
 * by then (a switch two objects set and clear every frame: CannonFleet 1's SwitchSynchronizerReverse and SwitchArea
 * on one SW_A, flapping within the frame as in Petari, made a rebind a frame; other changes set sw_changed as before) */
static unsigned char sw_seen[sizeof sw_bits];
static int sw_dirty;

static int sw_bit(const Row *r, int k, int add)
{
    int id = r->sw[k], n = (id >= 1000 ? id - 1000 : id) + add;
    if (id < 0 || n >= SW_PER_ZONE || r->zone >= MAX_ZONES) return -1;
    return (id >= 1000 ? 0 : (r->zone + 1) * SW_PER_ZONE) + n;
}

static int sw_on_n(const Row *r, int k, int add)
{
    int b = sw_bit(r, k, add);
    return b >= 0 && (sw_bits[b >> 3] >> (b & 7) & 1);
}
#define sw_on(r, k) sw_on_n(r, k, 0)

static void sw_set(const Row *r, int k, int on)
{
    int b = sw_bit(r, k, 0);
    if (b < 0 || (sw_bits[b >> 3] >> (b & 7) & 1) == on) return;
    sw_bits[b >> 3] ^= 1 << (b & 7);
    sw_dirty = 1;
}
