/* NPCActor's turning after Petari (NPCActor::turnToPlayer / turnToDefault, NPCUtil tryStartTurnAction /
 * tryStartTalkAction): MR::ActorTalkParam _0 turns to Mario within _4 (isNearPlayer), _1 while its talk runs, _8
 * degrees a frame (faceToVector: not when he is over 0.95 along its up), then its up tilted toward him at _C degrees a
 * frame up to _10 from the placement's (turnQuatYDirRad, clampVecAngleDeg); out of range (_0 or _1) back to the
 * placement's front (turnToDefault: blendQuatUpFront at _8 over the angle). NPCActor::setDefaults: 1, 1, 2000, 4, 0,
 * 0. Per class: Tico (TicoAstro) _C 0.5, _10 12 (Tico.cpp); Kinopio / KinopioAstro arg2 (mBehavior) 0 1 2 6 7 11
 * setNoTurnAction, 4 (Mount) _0 _1 off; Caretaker _0 off, _8 3; PenguinCoach _8 1; Rosetta and PenguinMaster
 * setMoveTalkNoTurnAction (no turn). TicoFat / TicoGalaxy (their own nerves), TicoShop (TicoComet), TicoReading and
 * CollectTico (LiveActors) do not turn here. Its action (tryStartAction, the clip of that name): _14 Wait when
 * turned (or not turning), _18 Turn while turning, _1C Talk / _20 TalkTurn while talking (NPCActor::setDefaults /
 * setDefaultAction: Wait, Turn, Talk, TalkTurn; Tico Wait, Wait, Talk, Talk; Kinopio's setTalkAction Talk, Talk; a
 * Kinopio setNoTurnAction mode its one action: arg2 0 1 2 SpinWait1 2 3, 6 Pickel, 7 Sleep, 11 Rightened).
 * Modes (npc_mode): Penguin arg0 0 Sit (SitDown / SitDownTalk, no turn), 1 Swim, 2 SwimSurface, 3 Dive, 4
 * SwimTurtle; HoneyBee arg0 3 Sleep / 4 Stick (no turn), 5 Gatekeeper, 7 Flustered, 1 2 6 8 9 their own nerves
 * (update_bees); Rabbit (TurnSmall) arg1 5 LongJump no turn. ponytail: no ActorAnimCtrl interpolation (the clip switches at
 * once); Kinopio's MoveTalk rail not ported (Penguin's: npc_rail_move) */
typedef struct { const char *cls; u8 near, talk; float dist, speed, tilt_speed, tilt_max; const char *act[4]; } NpcTurn;
static const NpcTurn npc_turns[] = {
    {"Tico", 1, 1, 2000.0f, 4.0f, 0.5f, 12.0f, {"wait", "wait", "talk", "talk"}},
    {"TicoAstro", 1, 1, 2000.0f, 4.0f, 0.5f, 12.0f, {"wait", "wait", "talk", "talk"}},
    {"TicoStarRing", 1, 1, 2000.0f, 4.0f, 0.5f, 12.0f, {"wait", "wait", "talk", "talk"}}, /* a Tico (Tico::init's params) */
    {"Kinopio", 1, 1, 2000.0f, 4.0f, 0, 0, {"wait", "turn", "talk", "talk"}},
    {"KinopioAstro", 1, 1, 2000.0f, 4.0f, 0, 0, {"wait", "turn", "talk", "talk"}},
    {"Penguin", 1, 1, 2000.0f, 4.0f, 0, 0, {"wait", "turn", "talk", "talkturn"}},
    {"PenguinCoach", 1, 1, 2000.0f, 1.0f, 0, 0, {"wait", "turn", "talk", "talkturn"}},
    {"PenguinStudent", 1, 1, 2000.0f, 4.0f, 0, 0, {"wait", "turn", "talk", "talkturn"}}, /* NPCActor::setDefaults (student_update) */
    {"Caretaker", 0, 1, 2000.0f, 3.0f, 0, 0, {"wait", "turn", "talk", "talkturn"}},
    {"HoneyBee", 1, 1, 2000.0f, 4.0f, 0, 0, {"wait", "turn", "talk", "talkturn"}},
    {"Rabbit", 1, 1, 2000.0f, 4.0f, 0, 0, {"wait", "turnsmall", "talk", "turnsmall"}}, /* Rabbit::init: TurnSmall */
    {"PenguinMaster", 0, 0, 2000.0f, 4.0f, 0, 0, {"wait", "wait", "talk", "talk"}}}; /* PenguinMaster::init: mParam _0 / _1 off, Wait / Talk */
static void npc_set(NpcTurn *m, const char *a0, const char *a1, const char *a2, const char *a3)
{
    m->act[0] = a0; m->act[1] = a1; m->act[2] = a2; m->act[3] = a3;
}
/* the row's mode (its class's args): its ActorTalkParam from its class's; 0 when its wait nerve is not a
 * tryStartTurnAction / TalkAction one (another nerve drives it) */
static int npc_mode(const NpcTurn *t, const Row *r, NpcTurn *m)
{
    *m = *t;
    if (!strncmp(t->cls, "Kinopio", 7)) { /* mBehavior (arg2) */
        int b = r->arg[2];
        static const char *const one[12] = {"spinwait1", "spinwait2", "spinwait3", NULL, NULL, NULL, "pickel", "sleep", NULL,
                                            NULL, NULL, "rightened"};
        if (b == 4) return 0; /* Mount */
        if (b == 5) npc_set(m, "swimwait", "swimwait", "swimwait", "swimwait");            /* setSingleAction */
        if (b == 9) npc_set(m, "kinopiogoodsweapon", "kinopiogoodsweaponturn", "kinopiogoodsweapon", "kinopiogoodsweaponturn");
        if (b == 10) npc_set(m, "joy", "joy", "joy", "joy");
        if (b == 12) npc_set(m, "starpiecewait", "starpiecewait", "starpiecewait", "starpiecewait");
        if (b >= 0 && b < 12 && one[b]) { npc_set(m, one[b], NULL, one[b], NULL); m->near = m->talk = 0; } /* setNoTurnAction */
    } else if (!strcmp(t->cls, "Penguin")) { /* mBehavior (arg0)
     * arg0 3 Dive, 4's jet sound and shell (penguin_turtle), TalkA / TalkB: penguin_wait. ponytail (unmarked until the 2026-11-02
     * audit): PenguinCoach / PenguinStudent: student_update, coach_takeout;
     * TicoRail's colour BRK by arg; Caretaker's BodyColor BRK at arg3 (its frames bake to one colour: the BRK drives registers tex.py does not bake) and Dirt BTK (frame 0), its
     * tidy-up mission (arg0 0: CountDown, Tidy, BombTimer, TakeOutStar; CareTaker.cpp:113-546) not ported (Rabbit: rabbit_lecture) */
        switch (r->arg[0]) {
        case 0: npc_set(m, "sitdown", NULL, "sitdowntalk", NULL); m->near = m->talk = 0; break; /* setMoveTalkNoTurnAction */
        case 1: m->act[0] = "swimwait"; m->act[1] = "swimwaittalk"; break;                  /* setMoveAction */
        case 2: m->act[0] = "swimwaitsurface"; m->act[1] = "swimsurfacetalk"; break;
        case 3: npc_set(m, "swimwaitsurface", "swimwaitsurface", "swimwaitsurface", "swimwaitsurface"); break;
        case 4: npc_set(m, "swimturtletalk", "swimturtletalk", "swimturtletalk", "swimturtletalk"); break;
        }
    } else if (!strcmp(t->cls, "Caretaker")) { /* Caretaker::init: arg0 -1 / 1 BWaitStand (move and turn), else Wait and
                                                * TalkNormal (the tidy-up mission's: its nerves not ported) */
        if (r->arg[0] == -1 || r->arg[0] == 1) { m->act[0] = m->act[1] = "bwaitstand"; }
        else npc_set(m, "wait", "wait", "talknormal", "talknormal");
    } else if (!strcmp(t->cls, "HoneyBee")) { /* mArg0 (arg0): its InitAction (the others: update_bees) */
        switch (r->arg[0]) {
        case 1: case 2: case 6: case 8: case 9: return 0; /* JumpLecture, Fly, DropLecture, FlyLectureA / B: own nerves */
        case 3: npc_set(m, "sleepwait", NULL, "sleepwait", NULL); m->near = m->talk = 0; break;
        case 4: npc_set(m, "stickwait", NULL, "stickwait", NULL); m->near = m->talk = 0; break;
        case 5: npc_set(m, "gatekeeperwait", "gatekeeperwait", "gatekeeperwait", "gatekeeperwait"); break;
        case 7: npc_set(m, "flustered", "flustered", "flustered", "flustered"); break;
        }
    } else if (!strcmp(t->cls, "Rabbit")) { /* mBehavior (arg1) */
        if (r->arg[1] == 3) m->near = m->talk = 0; /* arg1 3: Behavior_LongJump (Rabbit.cpp init) */
    }
    return 1;
}
static int npc_class(const char *name, const Row *r)
{
    for (unsigned i = 0; i < sizeof npc_turns / sizeof npc_turns[0]; i++) {
        NpcTurn m;
        if (!strcmp(name, npc_turns[i].cls)) return npc_mode(&npc_turns[i], r, &m) ? (int)i + 1 : 0;
    }
    return 0;
}

/* MapPartsRotator.cpp: the placement turned by row_angle about its own X / Y / Z axis (RotateAxis), about its origin */
static void rotor_matrix(Inst *in)
{
    const Row *r = &sc->objs[in->row];
    float base[16], rot[16];
    mat_translate_rot_scale(base, r->pos, r->rot, r->scale);
    int ax = r->arg[6] >= 0 && r->arg[6] <= 2 ? r->arg[6] : 0;
    V3 a = vnorm(v3(base[4 * ax], base[4 * ax + 1], base[4 * ax + 2]));
    float t = row_angle[in->row] * 0.0174533f, c = cosf(t), s = sinf(t), k = 1 - c;
    mat_identity(rot); /* axis-angle, column-major */
    rot[0] = c + a.x * a.x * k;       rot[4] = a.x * a.y * k - a.z * s; rot[8] = a.x * a.z * k + a.y * s;
    rot[1] = a.y * a.x * k + a.z * s; rot[5] = c + a.y * a.y * k;       rot[9] = a.y * a.z * k - a.x * s;
    rot[2] = a.z * a.x * k - a.y * s; rot[6] = a.z * a.y * k + a.x * s; rot[10] = c + a.z * a.z * k;
    base[12] = base[13] = base[14] = 0;
    mat_mul(in->m, rot, base);
    in->m[12] = r->pos[0]; in->m[13] = r->pos[1]; in->m[14] = r->pos[2];
}

/* AssemblyBlock.cpp. Its home (slice.py: the linked GeneralPos 合体ブロック故郷点, else 1000 up and along z; args 2-4
 * position, arg5 rx << 16 | ry, arg6 rz, degrees) and its place (the row). row_turn: 0 Wait (at home, turning 0.1
 * degree a frame about its local x, y and z: one turn about x + y + z; bobbing sin(step) along gravity a frame), 1
 * Assemble (home -> place in 10 frames), 2 AssembleWait, 3 Return (10 frames), 4 Timer; row_step its frames.
 * Its Blur effect while it flies (effect keeper "AssemblyBlock" for arg7 -1, else its own), the START / END / RETURN /
 * VANISH SEs (the _F ones for AssemblyBlockPartsTimerA), Timer: Disappear (tryStartAllAnim) sFlashTime 100 before it
 * vanishes; its bloom model goes with it (row_kill).
 * ponytail: the blend lerps the matrices and re-orthonormalizes, no slerp; collision stays on while it flies; only the
 * Disappear BCK (no BRK) */
static void assembly_home(const Row *r, float m[16])
{
    float pos[3] = {(float)r->arg[2], (float)r->arg[3], (float)r->arg[4]};
    float rot[3] = {(float)(r->arg[5] >> 16 & 0xFFFF), (float)(r->arg[5] & 0xFFFF), (float)r->arg[6]};
    mat_translate_rot_scale(m, pos, rot, r->scale);
}

static void assembly_place(Inst *in)
{
    const Row *r = &sc->objs[in->row];
    float h[16], p[16];
    int st = row_step[in->row], ph = row_turn[in->row];
    assembly_home(r, h);
    mat_translate_rot_scale(p, r->pos, r->rot, r->scale);
    if (ph == 0) { /* Wait */
        V3 a = vnorm(vadd(vadd(v3(h[0], h[1], h[2]), v3(h[4], h[5], h[6])), v3(h[8], h[9], h[10])));
        float t = (in->row & 1 ? 0.1732f : -0.1732f) * game_frame * 0.0174533f, c = cosf(t), s = sinf(t), k = 1 - c;
        float rot[16], base[16];
        mat_identity(rot);
        rot[0] = c + a.x * a.x * k;       rot[4] = a.x * a.y * k - a.z * s; rot[8] = a.x * a.z * k + a.y * s;
        rot[1] = a.y * a.x * k + a.z * s; rot[5] = c + a.y * a.y * k;       rot[9] = a.y * a.z * k - a.x * s;
        rot[2] = a.z * a.x * k - a.y * s; rot[6] = a.z * a.y * k + a.x * s; rot[10] = c + a.z * a.z * k;
        memcpy(base, h, 64);
        base[12] = base[13] = base[14] = 0;
        mat_mul(in->m, rot, base);
        V3 hp = v3(h[12], h[13], h[14]), d = vmul(in->gup, -57.3f * (1.0f - cosf(st * 0.0174533f)));
        in->m[12] = hp.x + d.x; in->m[13] = hp.y + d.y; in->m[14] = hp.z + d.z;
        return;
    }
    if (ph != 1 && ph != 3) { memcpy(in->m, p, 64); return; }
    float u = st >= 10 ? 1.0f : st / 10.0f;
    if (ph == 3) u = 1.0f - u;
    for (int j = 0; j < 16; j++) in->m[j] = h[j] + (p[j] - h[j]) * u;
    V3 x = vnorm(v3(in->m[0], in->m[1], in->m[2])), y = v3(in->m[4], in->m[5], in->m[6]);
    y = vnorm(vsub(y, vmul(x, vdot(x, y))));
    V3 z = vcross(x, y);
    float sc = r->scale[0];
    in->m[0] = x.x * sc; in->m[1] = x.y * sc; in->m[2] = x.z * sc;
    in->m[4] = y.x * sc; in->m[5] = y.y * sc; in->m[6] = y.z * sc;
    in->m[8] = z.x * sc; in->m[9] = z.y * sc; in->m[10] = z.z * sc;
}

static void carry(const float old[16], const Inst *in);
static void update_assembly(void)
{
    for (int i = 0; i < ninsts; i++) {
        Inst *in = &insts[i];
        if (!in->assembly) continue;
        const Row *r = &sc->objs[in->row];
        unsigned short *t = &row_step[in->row];
        signed char *ph = &row_turn[in->row];
        float dist = r->arg[0] > 0 ? (float)r->arg[0] : 2.0f * in->reach;
        float near = vlen(vsub(mario->pos, v3(r->pos[0], r->pos[1], r->pos[2])));
        int alive = life > 0;
        float old[16];
        memcpy(old, in->m, 64);
        if (*t < 0xFFFF) ++*t;
        const char *cn = sc->types + 32 * r->type;
        int tf = !strcmp(cn, "AssemblyBlockPartsTimerA"), timer = r->arg[1] != -1 ? r->arg[1] : 300; /* _13C; mTimer (arg1 NoInit) */
        float *at = &in->m[12];
        if (*ph == 0 && near < dist && alive) { *ph = 1; *t = 0; se_start(tf ? SE_OJ_ASSEMBLE_BLOCK_ST_F : SE_OJ_ASSEMBLE_BLOCK_START, at); }
        else if (*ph == 1 && *t >= 10) { /* isStep(sStepForAssemble): END, AssembleWait (rumble) */
            se_start(tf ? SE_OJ_ASSEMBLE_BLOCK_ED_F : SE_OJ_ASSEMBLE_BLOCK_END, at);
            *ph = r->arg[7] == 0 ? 4 : 2; *t = 0; pad_rumble(RUMBLE_WEAK);
        }
        else if (*ph == 2 && near > dist + 50.0f && alive) { *ph = 3; *t = 0; pad_rumble(RUMBLE_WEAK); se_start(tf ? SE_OJ_ASSEMBLE_BLOCK_RET_F : SE_OJ_ASSEMBLE_BLOCK_RETURN, at); } /* exeReturn */
        else if (*ph == 3 && *t >= 10) { *ph = 0; *t = 0; }
        else if (*ph == 4 && *t == timer - 100) obj_play(in, "disappear", 0, 0); /* tryStartAllAnim(Disappear) at mTimer - sFlashTime */
        else if (*ph == 4 && *t >= timer) {
            se_start(tf ? SE_OJ_ASSEMBLE_BLOCK_VAN_F : SE_OJ_ASSEMBLE_BLOCK_VANISH, at);
            printf("assembly block %d vanishes\n", in->row);
            row_kill(in->row); game_rebind(); return;
        }
        if (*ph == 1 || *ph == 3) fx_named(r->arg[7] == -1 ? "AssemblyBlock" : cn, "Blur", in->m, NULL, &row_turn[in->row]); /* emitEffect Blur, deleted in AssembleWait / Wait */
        assembly_place(in);
        if (mario_ground == i) carry(old, in);
    }
}

/* Tsukidashikun.cpp: on its rail from the nearest point to its placement; Relax until SW_B (if it has one), Wait arg1
 * frames (default 120), Sign 60, Move at arg0 (default 10) to the rail's end, reverse, Wait, Sign, Move back... row_turn
 * 0 not started, 1 relax, 2 wait, 3 sign, 4 move; row_rdir its direction (+1 / -1); row_coord, row_step. ponytail: no
 * Sign shake (its BCK) */
static float tsuki_len(const unsigned char *e)
{
    u32 np = *(const u32 *)(e + 8), nr = *(const u32 *)(e + 12);
    return *(const float *)(e + 24 + 12 * np + 12 * nr + 12 * (nr - 1));
}

