        wp_activate(insts[i].row); wp_activate(warp_pair(insts[i].row));
        mario->pos = vadd(v3(r->pos[0], r->pos[1], r->pos[2]), vmul(row_axis_y(r), 10.0f - HIT_BODY_H));
        mario->hvel = v3(0, 0, 0); mario->vup = 0;
