int game_test_flip_front(void) /* tests: Mario onto the first panel still on its front side; -1 when none is */
{
    for (int i = 0; i < ninsts; i++)
        if (insts[i].flip && !(row_step[insts[i].row] & (FLIP_BACK | FLIP_DONE))) {
            static int last = -1, same;
            same = insts[i].row == last ? same + 1 : 0; last = insts[i].row;
            if (same >= 3) { row_step[insts[i].row] |= FLIP_BACK; same = 0; return insts[i].row; } /* (a panel the drop misses: flipped here) */
            int k = 0;
            for (int j = 0; j < i; j++) k += insts[j].flip != 0;
            return game_test_flip(k);
        }
    return -1;
}
int game_test_flip(int k)
{
    for (int i = 0; i < ninsts; i++) {
        if (!insts[i].flip || k--) continue;
        V3 p = v3(insts[i].m[12], insts[i].m[13], insts[i].m[14]);
        V3 y = vnorm(v3(insts[i].m[4], insts[i].m[5], insts[i].m[6])); /* the panel's own up: side panels' origins
                                                                           * lie outside their face's gravity box */
        mario->pos = vadd(p, vmul(y, 200.0f)); /* the panel's top is about 100 up its axis */
        mario->up = up_at(mario->pos, y);
        mario->hvel = v3(0, 0, 0); mario->vup = 0;
        return insts[i].row;
    }
    return -1;
}

int game_flips_back(void)
{
    int n = 0;
    for (int i = 0; i < ninsts; i++) n += insts[i].flip && (row_step[insts[i].row] & FLIP_BACK);
    return n;
}

